#include "PrintIssue.hpp"

#include <algorithm>
#include <functional>

namespace Slic3r::GUI::JusPrin::PrintIssues {

const char* source_name(IssueSource source)
{
    switch (source) {
    case IssueSource::Notice:       return "notice";
    case IssueSource::Validation:   return "validation";
    case IssueSource::Placement:    return "placement";
    case IssueSource::SliceStep:    return "slice_step";
    case IssueSource::SliceResult:  return "slice_result";
    case IssueSource::SliceFailure: return "slice_failure";
    }
    return "";
}

const char* severity_name(IssueSeverity severity) { return severity == IssueSeverity::Blocker ? "blocker" : "warning"; }

bool Notice::operator==(const Notice& other) const
{
    return kind == other.kind && route == other.route && level == other.level && text == other.text;
}

bool PrintIssue::operator==(const PrintIssue& other) const
{
    return id == other.id && source == other.source && severity == other.severity && code == other.code &&
           setting == other.setting && message == other.message && plate == other.plate && object == other.object &&
           instance == other.instance && object_name == other.object_name && stale == other.stale && ignored == other.ignored;
}

const PrintIssue* PrintIssueSnapshot::find(const std::string& id) const
{
    const auto found = std::find_if(issues.begin(), issues.end(), [&id](const PrintIssue& issue) { return issue.id == id; });
    return found == issues.end() ? nullptr : &*found;
}

bool PrintIssueSnapshot::same_content(const PrintIssueSnapshot& other) const
{
    return session == other.session && plate == other.plate && checked == other.checked && slicing == other.slicing &&
           sliced == other.sliced && issues == other.issues && notices == other.notices;
}

std::vector<PrintIssue> issues_from(const std::vector<Notice>& held, std::vector<PrintIssue> found, std::uint64_t plate)
{
    const auto holds = [&held](int kind) {
        return std::any_of(held.begin(), held.end(), [kind](const Notice& notice) { return notice.kind == kind; });
    };
    std::vector<PrintIssue> issues;
    for (PrintIssue& issue : found)
        if (issue.unprompted || (issue.answers >= 0 && holds(issue.answers)))
            issues.push_back(std::move(issue));

    const std::size_t answered = issues.size();
    for (const Notice& notice : held) {
        if (notice.route != NoticeRoute::Issue)
            continue;
        if (std::any_of(issues.begin(), issues.begin() + answered, [&notice](const PrintIssue& issue) { return issue.answers == notice.kind; }))
            continue;
        PrintIssue issue;
        issue.source   = IssueSource::Notice;
        issue.severity = notice.level == NoticeLevel::Error ? IssueSeverity::Blocker : IssueSeverity::Warning;
        issue.code     = notice.kind_name;
        issue.message  = notice.body;
        issue.plate    = plate;
        issue.answers  = notice.kind;
        // One of a kind is that kind. Where OrcaSlicer keeps several apart by
        // their words, so does this: its words now against its words before.
        issue.id = "notice:" + notice.kind_name + (notice.several ? ":" + std::to_string(std::hash<std::string>{}(notice.text)) : std::string());
        issues.push_back(std::move(issue));
    }
    return issues;
}

void mark_ignored(std::vector<PrintIssue>& issues, std::set<std::string>& ignored, bool settled)
{
    std::set<std::string> reported;
    for (PrintIssue& issue : issues) {
        issue.ignored = issue.severity == IssueSeverity::Warning && ignored.count(issue.id) != 0;
        if (issue.ignored)
            reported.insert(issue.id);
    }
    if (settled)
        ignored = std::move(reported);
}

std::optional<Workspace::SliceFailure> slice_failure_of(const PrintIssueSnapshot& snapshot)
{
    for (const IssueSource source : {IssueSource::Validation, IssueSource::Placement, IssueSource::SliceFailure, IssueSource::Notice})
        for (const PrintIssue& issue : snapshot.issues) {
            if (issue.source != source || issue.severity != IssueSeverity::Blocker)
                continue;
            Workspace::SliceFailure failure;
            failure.kind     = source == IssueSource::SliceFailure ? Workspace::SliceFailureKind::Failed :
                                                                     Workspace::SliceFailureKind::Refused;
            failure.severity = severity_name(issue.severity);
            // OrcaSlicer ends some of its messages with a line break.
            failure.message  = issue.message.substr(0, issue.message.find_last_not_of(" \n") + 1);
            failure.setting  = issue.setting;
            failure.code     = issue.code;
            if (issue.object != 0) {
                failure.object      = Workspace::ObjectId(Workspace::ProjectSessionId(snapshot.session), issue.object);
                failure.object_name = issue.object_name;
            }
            return failure;
        }
    return std::nullopt;
}

std::optional<std::vector<Workspace::SliceWarningFinding>> slice_warnings_of(const PrintIssueSnapshot& snapshot)
{
    if (!snapshot.checked || snapshot.slicing || !snapshot.sliced || snapshot.plate == 0)
        return std::nullopt;
    std::vector<Workspace::SliceWarningFinding> findings;
    for (const PrintIssue& issue : snapshot.issues) {
        if (issue.severity != IssueSeverity::Warning || issue.stale || issue.plate != snapshot.plate)
            continue;
        // Every warning the chip lists, the bed-temperature one (1000C001)
        // and the traditional-timelapse copy for older firmware (1000C003)
        // among them, though slice_report leaves those two out as
        // OrcaSlicer's send dialog does: the model is told what the person
        // is shown.
        Workspace::SliceWarningFinding finding;
        finding.id = issue.id;
        // A step's critical warning, and the two paths that cross: what
        // OrcaSlicer raises as a serious warning rather than a plain one.
        const std::string critical = ":critical";
        finding.critical = (issue.code.size() > critical.size() &&
                            issue.code.compare(issue.code.size() - critical.size(), critical.size(), critical) == 0) ||
                           issue.code == "gcode_path_conflict" || issue.code == "SlicingSeriousWarning";
        finding.message     = issue.message;
        finding.setting     = issue.setting;
        finding.code        = issue.code;
        finding.object      = issue.object;
        finding.object_name = issue.object_name;
        finding.ignored     = issue.ignored;
        findings.push_back(std::move(finding));
    }
    return findings;
}

} // namespace Slic3r::GUI::JusPrin::PrintIssues
#pragma once

// The per-plate summary of what OrcaSlicer warned about in a slice: how many
// warnings and the one to read first. Plain data, so the rule can be tested
// without the application.

#include "Workspace.hpp"

#include <algorithm>
#include <set>
#include <vector>

namespace Slic3r::GUI::JusPrin::Workspace {

// The summary of `findings`, numbered `sequence`; nothing when there are none.
inline std::optional<SliceWarnings> summarize_slice_warnings(const std::vector<SliceWarningFinding>& findings,
                                                             ProjectSessionId session, std::uint64_t sequence)
{
    if (findings.empty())
        return std::nullopt;
    // Critical first, then one the person has not ignored; otherwise
    // OrcaSlicer's order.
    const auto rank = [](const SliceWarningFinding& finding) { return (finding.critical ? 0 : 2) + (finding.ignored ? 1 : 0); };
    const auto top  = std::min_element(findings.begin(), findings.end(),
                                       [&rank](const SliceWarningFinding& a, const SliceWarningFinding& b) { return rank(a) < rank(b); });
    SliceWarnings summary;
    summary.count       = findings.size();
    summary.ignored     = std::size_t(std::count_if(findings.begin(), findings.end(),
                                                    [](const SliceWarningFinding& finding) { return finding.ignored; }));
    summary.severity    = top->critical ? "critical" : "warning";
    summary.message     = top->message;
    summary.setting     = top->setting;
    summary.code        = top->code;
    summary.object_name = top->object_name;
    if (top->object != 0)
        summary.object = ObjectId(session, top->object);
    summary.sequence = sequence;
    return summary;
}

// Whether `findings` holds a warning `known` (the ids of the plate's last
// record) does not: the moment a reader has something new to be told.
inline bool has_new_slice_warning(const std::vector<SliceWarningFinding>& findings, const std::set<std::string>& known)
{
    return std::any_of(findings.begin(), findings.end(),
                       [&known](const SliceWarningFinding& finding) { return known.count(finding.id) == 0; });
}

} // namespace Slic3r::GUI::JusPrin::Workspace

